def solve_lshaped(input_grid):
    h, w = len(input_grid), len(input_grid[0])
    out = [[input_grid[r][c] for c in range(w)] for r in range(h)]

    r_b, c_b, r_p, c_p = None, None, None, None
    for r in range(h):
        for c in range(w):
            if input_grid[r][c] == 1:
                r_b, c_b = r, c
            elif input_grid[r][c] == 2:
                r_p, c_p = r, c

    if r_b is None or r_p is None:
        return out

    if r_b == r_p and c_b == c_p:
        return out

    abs_dr, abs_dc = abs(r_p - r_b), abs(c_p - c_b)

    if abs_dr == abs_dc:
        dr = 1 if r_b < r_p else -1
        dc = 1
        for kr in range(1, max(abs_dr, abs_dc) + 1):
            r, c = r_b + kr * dr, c_b + kr * dc
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = 3
    elif r_b == r_p:
        for c in range(min(c_b, c_p), max(c_b, c_p) + 1):
            out[r_b][c] = 3
    elif c_b == c_p:
        for r in range(min(r_b, r_p), max(r_b, r_p) + 1):
            out[r][c_b] = 3
    else:
        for r in range(min(r_b, r_p), max(r_b, r_p) + 1):
            out[r][c_b] = 3
        for c in range(min(c_b, c_p), max(c_b, c_p) + 1):
            out[r_p][c] = 3

    return out

